// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import { encodeWorkspace } from "../../../main/frontend/graph-explorer/workspace-format.ts";
import {
  WORKSPACE_LIMITS,
  parseWorkspacePayload,
  prepareWorkspaceSave,
  recoverWorkspacePayload,
  saveNotice,
  trimLoadHistory,
} from "../../../main/frontend/graph-explorer/workspace.ts";
import {
  discardUnreadableWorkspace,
  loadWorkspaceText,
  openStoredWorkspace,
  recoverUnreadableWorkspace,
  saveWorkspaceText,
} from "../../../main/frontend/graph-explorer/workspace-storage.ts";
import { mergeTriples } from "../../../main/frontend/graph-explorer/graph-operations.ts";
import { bindingsToTriples } from "../../../main/frontend/graph-explorer/graph-terms.ts";

// A stored graph that breaks one of the limits parseWorkspacePayload enforces is refused whole when the page opens,
// so the page opened empty without a word. Saving keeps within those limits, says what it left out, and a graph that
// still cannot be opened is set aside where the page can recover it.

const uri = (value) => ({ type: "uri", value });
const load = (index, extra = {}) => ({
  id: `batch-${index}`,
  label: `Expanded node ${index}`,
  endpoint: "/workbench/graph",
  query: `DESCRIBE <urn:n${index}>`,
  tripleCount: 2,
  loadedAt: new Date(Date.UTC(2026, 9, 20, 0, 0, index)).toISOString(),
  limit: null,
  complete: true,
  ...extra,
});

function workspace(rows, extra = {}) {
  return {
    graph: mergeTriples({ nodes: [], edges: [], revision: 0 }, bindingsToTriples(rows), false, "batch-0"),
    transform: { x: 0, y: 0, k: 1 },
    query: "CONSTRUCT WHERE { ?s ?p ?o } LIMIT 100",
    endpointId: "rdf4j:repo",
    customUrl: "",
    provenanceBatches: [load(0)],
    namedGroups: [],
    selectedNodeIds: [],
    focusedNodeId: null,
    scope: "default",
    savedAt: "2026-10-20T00:00:00.000Z",
    ...extra,
  };
}

const friends = [
  { source: uri("urn:alice"), predicate: uri("urn:knows"), target: uri("urn:bob") },
  { source: uri("urn:bob"), predicate: uri("urn:knows"), target: uri("urn:carol") },
];

function reopen(raw) {
  const restored = parseWorkspacePayload(raw, { repositoryReferences: true });
  assert.ok(restored, "the saved graph opens again");
  return restored;
}

test("every Expand adds a Load history entry; a long session's oldest entries are merged when it is saved", () => {
  const loads = Array.from({ length: 1500 }, (_, index) => load(index, index === 3 ? { complete: false, limit: 2 } : {}));
  const before = encodeWorkspace(workspace(friends, { provenanceBatches: loads }));
  assert.equal(parseWorkspacePayload(before, { repositoryReferences: true }), null, "unchecked, the graph would not open");

  const prepared = prepareWorkspaceSave(workspace(friends, { provenanceBatches: loads }));
  const restored = reopen(prepared.raw);
  assert.equal(restored.graph.nodes.length, 3);
  assert.equal(restored.provenanceBatches.length, WORKSPACE_LIMITS.loads);
  const kept = WORKSPACE_LIMITS.loads - 1;
  assert.deepEqual(restored.provenanceBatches.slice(1).map((batch) => batch.id), loads.slice(-kept).map((batch) => batch.id),
    "the newest loads are kept as they were");
  const merged = restored.provenanceBatches[0];
  const mergedCount = loads.length - kept;
  assert.match(merged.label, new RegExp(`${mergedCount.toLocaleString()} earlier loads`));
  assert.equal(merged.tripleCount, mergedCount * 2);
  assert.equal(merged.loadedAt, loads[0].loadedAt, "dated by the oldest load it holds");
  assert.equal(merged.complete, false, "one of the merged loads was cut by its limit");
  assert.equal(merged.mergedLoads, mergedCount);
  assert.deepEqual(prepared.leftOut, [], "merging the Load history loses no statement, so nothing is reported");
  assert.equal(saveNotice(prepared), null);
});

test("merging again counts the loads an earlier merge already holds", () => {
  const once = trimLoadHistory(Array.from({ length: 1200 }, (_, index) => load(index)));
  const twice = trimLoadHistory([...once, ...Array.from({ length: 300 }, (_, index) => load(5000 + index))]);
  assert.equal(twice.length, WORKSPACE_LIMITS.loads);
  assert.equal(twice[0].mergedLoads, 1500 - (WORKSPACE_LIMITS.loads - 1));
  assert.equal(twice[0].tripleCount, twice[0].mergedLoads * 2);
  const few = [load(1), load(2)];
  assert.equal(trimLoadHistory(few), few, "a history within the limit is kept as it is");
});

test("a value too long to store is left out with its links, the rest is saved, and the page says so", () => {
  const huge = "x".repeat(WORKSPACE_LIMITS.characters + 1);
  const rows = [...friends, { source: uri("urn:alice"), predicate: uri("urn:wkt"), target: { type: "literal", value: huge } }];
  const prepared = prepareWorkspaceSave(workspace(rows, { query: huge }));
  const restored = reopen(prepared.raw);
  assert.deepEqual(restored.graph.nodes.map((node) => node.id).sort(), ["urn:alice", "urn:bob", "urn:carol"]);
  assert.equal(restored.graph.edges.length, 2);
  assert.equal(restored.query, "", "the query in the editor was too long as well");
  assert.equal(prepared.leftOut.length, 3, prepared.leftOut.join(" | "));
  const notice = saveNotice(prepared);
  assert.match(notice, /saved without/);
  assert.ok(notice.includes(`1 node with a value over ${WORKSPACE_LIMITS.characters.toLocaleString()} characters`), notice);
  assert.match(notice, /1 link\b/);
  assert.match(notice, /the query in the editor/);
});

test("a node keeps the first types a saved graph can hold", () => {
  const payload = workspace(friends);
  const types = Array.from({ length: WORKSPACE_LIMITS.typesPerNode + 6 }, (_, index) => ({ id: `urn:T${index}`, label: `T${index}` }));
  payload.graph = { ...payload.graph, nodes: payload.graph.nodes.map((node) => (node.id === "urn:bob" ? { ...node, types } : node)) };
  const prepared = prepareWorkspaceSave(payload);
  const bob = reopen(prepared.raw).graph.nodes.find((node) => node.id === "urn:bob");
  assert.deepEqual(bob.types, types.slice(0, WORKSPACE_LIMITS.typesPerNode));
  assert.ok(saveNotice(prepared).includes(`types beyond the first ${WORKSPACE_LIMITS.typesPerNode} of 1 node`));
});

test("links to nodes that are not in the graph, and named groups beyond the limit, are not saved", () => {
  const payload = workspace(friends);
  const stray = { id: "stray", source: "urn:alice", predicate: "urn:knows", label: "knows", target: "urn:nobody" };
  payload.graph = { ...payload.graph, edges: [...payload.graph.edges, stray] };
  payload.namedGroups = Array.from({ length: WORKSPACE_LIMITS.groups + 2 }, (_, index) => ({
    id: `g${index}`, name: `Group ${index}`, color: "#123456", nodeIds: ["urn:alice"],
  }));
  const prepared = prepareWorkspaceSave(payload);
  const restored = reopen(prepared.raw);
  assert.equal(restored.graph.edges.length, 2);
  assert.equal(restored.namedGroups.length, WORKSPACE_LIMITS.groups);
  assert.equal(restored.namedGroups.at(-1).id, `g${WORKSPACE_LIMITS.groups + 1}`, "the newest groups are kept");
  assert.match(saveNotice(prepared), /1 link\b.*2 named groups/);
});

test("a graph larger than a saved graph can be is not written, and the page says why", () => {
  const nodes = Array.from({ length: WORKSPACE_LIMITS.nodes + 1 }, (_, index) => ({ id: `urn:n${index}`, label: `n${index}`, kind: "iri" }));
  const tooMany = prepareWorkspaceSave(workspace([], { graph: { nodes, edges: [], revision: 1 } }));
  assert.equal(tooMany.raw, null);
  assert.ok(tooMany.reason.includes(`${(WORKSPACE_LIMITS.nodes + 1).toLocaleString()} nodes`), tooMany.reason);
  assert.match(saveNotice(tooMany), /not saved/);

  // Each label is within the length limit; together, in UTF-8, they are over the size limit.
  const label = "😀".repeat(Math.floor(WORKSPACE_LIMITS.characters / 2) - 1);
  const big = Array.from({ length: 34 }, (_, index) => ({ id: `urn:big${index}`, label, kind: "iri" }));
  const tooLarge = prepareWorkspaceSave(workspace([], { graph: { nodes: big, edges: [], revision: 1 } }));
  assert.equal(tooLarge.raw, null);
  assert.match(tooLarge.reason, /64 MB/);
});

test("a graph that fits is saved in the same compact form as before", () => {
  const payload = workspace(friends);
  const prepared = prepareWorkspaceSave(payload);
  assert.equal(prepared.raw, encodeWorkspace(payload));
  assert.deepEqual(prepared.leftOut, []);
});

test("a stored graph the page cannot open is recovered: what fits comes back, what did not is named", () => {
  const huge = "y".repeat(WORKSPACE_LIMITS.characters + 1);
  const rows = [...friends, { source: uri("urn:carol"), predicate: uri("urn:wkt"), target: { type: "literal", value: huge } }];
  const stored = encodeWorkspace(workspace(rows, { provenanceBatches: Array.from({ length: 1200 }, (_, index) => load(index)) }));
  assert.equal(parseWorkspacePayload(stored, { repositoryReferences: true }), null);
  const recovered = recoverWorkspacePayload(stored);
  assert.ok(recovered);
  assert.deepEqual(recovered.payload.graph.nodes.map((node) => node.id).sort(), ["urn:alice", "urn:bob", "urn:carol"]);
  assert.equal(recovered.payload.graph.edges.length, 2);
  assert.equal(recovered.payload.provenanceBatches.length, WORKSPACE_LIMITS.loads);
  assert.equal(recovered.leftOut.length, 2, recovered.leftOut.join(" | "));
  assert.equal(recoverWorkspacePayload("not a graph"), null);
  assert.equal(recoverWorkspacePayload(JSON.stringify({ graph: { nodes: [], edges: [] } })), null, "nothing to recover");
});

function memoryStorage() {
  const items = new Map();
  return {
    items,
    getItem: (key) => (items.has(key) ? items.get(key) : null),
    setItem: (key, value) => void items.set(key, String(value)),
    removeItem: (key) => void items.delete(key),
  };
}

test("an unreadable stored graph is set aside and reported until it is recovered or discarded", async () => {
  // No IndexedDB here: the storage falls back to localStorage, as in a browser that blocks the database.
  globalThis.localStorage = memoryStorage();
  try {
    const scope = "server|repo";
    const unreadable = encodeWorkspace(workspace(friends, { provenanceBatches: Array.from({ length: 1001 }, (_, index) => load(index)) }));
    await saveWorkspaceText(unreadable, scope);

    const opened = await openStoredWorkspace(scope);
    assert.equal(opened.saved, null);
    assert.equal(opened.unreadable, true, "the page says the stored graph could not be opened");
    assert.equal(await loadWorkspaceText(`${scope}:unreadable`), unreadable, "it was set aside before anything is saved over it");

    // The page then saves a new graph; the set-aside one is still reported the next time the page opens.
    await saveWorkspaceText(prepareWorkspaceSave(workspace([friends[0]])).raw, scope);
    const reopened = await openStoredWorkspace(scope);
    assert.equal(reopened.saved.graph.nodes.length, 2);
    assert.equal(reopened.unreadable, true);

    const recovered = await recoverUnreadableWorkspace(scope);
    assert.equal(recovered.payload.graph.nodes.length, 3);
    assert.equal(recovered.saved, true);
    assert.equal(await loadWorkspaceText(`${scope}:unreadable`), null, "the recovered graph replaced the one set aside");
    const after = await openStoredWorkspace(scope);
    assert.equal(after.unreadable, false);
    assert.equal(after.saved.graph.nodes.length, 3, "the recovered graph is the stored one");
    assert.equal(after.saved.savedAt, recovered.payload.savedAt);

    await saveWorkspaceText("{\"graph\":", scope);
    assert.equal((await openStoredWorkspace(scope)).unreadable, true);
    assert.equal(await recoverUnreadableWorkspace(scope), null, "nothing in it can be read");
    await discardUnreadableWorkspace(scope);
    assert.equal(await loadWorkspaceText(`${scope}:unreadable`), null);
    assert.equal(await loadWorkspaceText(scope), null, "not set aside again the next time the page opens");
    assert.deepEqual(await openStoredWorkspace(scope), { saved: null, unreadable: false });
  } finally {
    delete globalThis.localStorage;
  }
});
